-- 0045  Upbrains invoice extraction, from the flow in the client's workspace.
--
-- Upbrains is one of the thirteen APIs the client designated on 6 October
-- 2026. Migration 0040 left it out because it publishes no specification. On
-- 11 October the client gave the group access to their own Upbrains
-- workspace. Upbrains has no fixed public API: a workspace builds a flow that
-- starts with a Webhook trigger, runs a Document Skills extractor and ends
-- with a Return Response step, and that webhook is what a client calls.
--
-- The record below describes the flow "BP Builer - Invoice PDF Extract" in
-- that workspace: POST a JSON body carrying the PDF as base64 (fileBase64),
-- receive the Standard Invoice Extractor's result as JSON. The group wrote an
-- OpenAPI document from the flow's configuration and from the request and
-- response of the test run saved in the flow
-- (frontend/public/specs/upbrains-invoice-extract-openapi.json,
-- sha256 a2d27dc92395074edce94176065b027e65118d8008cc2e49cf74ab7e3011e902),
-- and built the rows with the importer's own code -- detect, parseOpenApi3,
-- toApiRow, extractDocumentSchemas, toSchemaRows, toFieldRows,
-- toParameterRows -- as migration 0040 did.
--
-- Set by hand: the readable name; the category (the importer says
-- Communication; extraction is a kind of Transformation in the client's
-- taxonomy); the official company name and website.
--
-- Limits, stated in the document and in the record:
--   * The group has not called the webhook itself. The response schema is
--     inferred from the saved test run, whose display the console cuts short
--     after the field VendorAddressRecipient; fields is open to further keys.
--   * The endpoint keeps {flowId} as a placeholder. The flow's webhook has no
--     token, so its address is the secret; it is not stored in the catalogue.
--   * The output is Upbrains' own JSON, not an invoice standard. A conversion
--     to UBL XML has to follow it (client, 10 October 2026).
--
-- The older record UpbrainsXtract (inactive since migration 0034: no schema)
-- is left as it is. The new record arrives as Published; an administrator verifies it in the
-- application.

-- ----------------------------------------------------------------- preconditions

create temporary table _0045_api on commit drop as
select * from jsonb_populate_recordset(null::public.apis, $rows0045$[{"api_name":"Upbrains Extract Invoice From PDF API","official_api_name":"extractInvoiceFromPdf","description":"Starts the flow with a PDF carried as base64 inside a JSON body and returns the extraction result of the Standard Invoice Extractor. The same address followed by /test runs the flow's draft in test mode.","api_endpoint":"https://agents.upbrains.ai/v1/webhooks/{flowId}","company_name":"Upbrains","company_name_original":"Upbrains","official_company_name":"UpBrains AI, Inc.","documentation_url":"https://workflow.upbrains.ai","source_url":"https://workflow.upbrains.ai","http_method":"POST","category":"Transformation","communication_direction":"","authentication_method":"None","authentication_other":"","input_formats":["JSON"],"input_formats_original":["application/json"],"output_formats":["JSON"],"output_formats_original":["application/json"],"data_quality":"ok","access_scope":"public","review_status":"Published","id":"974405cd-82b2-4e76-a628-278a56ac4e9a","network":"","website_url":"https://www.upbrains.ai/","authentication_details":"The flow the record was written from has a webhook with Token Type None, so no credential is sent; the webhook address carries the flow identifier, is private to the workspace and is not published here."}]$rows0045$::jsonb);

do $$
declare clash integer;
begin
  select count(*) into clash
    from _0045_api new_api
    join public.apis api
      on (lower(api.company_name) = lower(new_api.company_name) and lower(api.api_name) = lower(new_api.api_name))
      or (api.documentation_url = new_api.documentation_url and api.api_endpoint = new_api.api_endpoint
          and api.http_method = new_api.http_method);
  if clash <> 0 then
    raise exception '0045 precondition failed: the Upbrains extraction operation already exists.';
  end if;
end
$$;

