insert into public.api_audit_events (
  api_id, api_name, company_name, action, actor_name, actor_user_id, details
)
select id, api_name, company_name, 'upload', 'System migration', null,
       'API added by migration 0045 from the configuration and saved test run of a flow in the client''s Upbrains workspace, viewed on 11 October 2026 (one of the thirteen designated APIs).'
  from _0045_api;

-- ------------------------------------------------------------------ postcondition

do $$
declare
  added integer;
  schema_rows integer;
  field_rows integer;
  parameter_rows integer;
begin
  select count(*) into added from public.apis where id in (select id from _0045_api);
  select count(*) into schema_rows from public.api_schema where api_id in (select id from _0045_api);
  select count(*) into field_rows
    from public.api_schema_field f join public.api_schema s on s.id = f.schema_id
   where s.api_id in (select id from _0045_api);
  select count(*) into parameter_rows from public.api_parameter where api_id in (select id from _0045_api);
  if added <> 1 or schema_rows <> 2 or field_rows <> 199 or parameter_rows <> 1 then
    raise exception '0045 postcondition failed: % APIs, % schemas, % fields, % parameters.', added, schema_rows, field_rows, parameter_rows;
  end if;
end
$$;
